package com.ilp.bank;

import java.util.*;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

// WebController.java: builds the page from your steps. Students do NOT edit this file.
// Day 2: steps 1-5.   Day 3: steps 6-10.
@RestController
public class WebController {
    static Account account = null;
    static final List<String> history = new ArrayList<>();
    static String msg = "";
    static boolean ok = true;
    static final String HTML = "text/html;charset=UTF-8";

    static String money(double x) {
        return x == Math.floor(x) ? String.valueOf((long) x) : String.format("%.2f", x);
    }

    @GetMapping(value = "/", produces = HTML)
    public String home() {
        String m = msg.isEmpty() ? "" : "<div class=\"msg " + (ok ? "ok" : "bad") + "\">" + msg + "</div>";
        String main;
        if (account == null) {
            main = "<div class=\"card\">" + Ui.part(1, Step01Header::header) + m
                + "<h2>Open a new account</h2><form method=\"post\" action=\"/open\">" + Ui.part(2, Step02NameBox::nameBox)
                + (Checks.done(3) ? "<button>Open account</button>" : "") + "</form>" + (Checks.done(3) ? "" : Ui.box(3)) + "</div>";
        } else {
            Account shown = new Account(Ui.esc(account.name), account.balance);
            String btns = (Checks.done(5) ? "<button name=\"action\" value=\"deposit\">Deposit</button>" : "")
                + (Checks.done(6) ? "<button class=\"alt\" name=\"action\" value=\"withdraw\">Withdraw</button>" : "");
            StringBuilder todo = new StringBuilder();
            for (int n : new int[] { 5, 6, 7, 8 }) if (!Checks.done(n)) todo.append(Ui.box(n));
            main = "<div class=\"card\">" + Ui.part(1, Step01Header::header) + "<p>Account holder: <b>" + shown.name + "</b></p>"
                + Ui.part(4, () -> Step04ShowBalance.balanceHtml(shown)) + m
                + "<form method=\"post\" action=\"/money\"><input name=\"amount\" type=\"number\" placeholder=\"Amount ₹\">" + btns + "</form>"
                + todo
                + (Checks.done(10) ? "<form method=\"post\" action=\"/interest\"><button class=\"amber\">Add 4% interest</button></form>" : Ui.box(10))
                + "<p><a href=\"/close\" style=\"color:#6b7480\">Close account (start again)</a></p></div>";
            if (Checks.done(9)) {
                StringBuilder items = new StringBuilder();
                for (int i = history.size() - 1; i >= 0; i--) items.append("<li>").append(Ui.esc(history.get(i))).append("</li>");
                if (history.isEmpty()) items.append("<li style=\"color:#6b7480\">No transactions yet</li>");
                main += "<div class=\"card\"><h2>History</h2><ul>" + items + "</ul></div>";
            } else main += "<div class=\"card\"><h2>History</h2>" + Ui.box(9) + "</div>";
        }
        return Ui.page(main);
    }

    @PostMapping("/open")
    public ResponseEntity<Void> open(@RequestParam(defaultValue = "") String name) {
        String n = name.trim().isEmpty() ? "Customer" : name.trim();
        if (Checks.done(3)) {
            account = Step03CreateAccount.createAccount(n);
            history.clear(); ok = true; msg = "Account opened for " + Ui.esc(n) + " ✅";
        }
        return home302();
    }

    @PostMapping("/money")
    public ResponseEntity<Void> money(@RequestParam(defaultValue = "0") String amount, @RequestParam(defaultValue = "") String action) {
        double a;
        try { a = Double.parseDouble(amount.trim()); } catch (NumberFormatException e) { a = 0; }
        if (account == null || !(action.equals("deposit") || action.equals("withdraw"))) return home302();
        if (Checks.done(8) && !Step08ValidAmount.validAmount(a)) { msg = "Enter an amount more than ₹0 ❌"; ok = false; }
        else if (action.equals("withdraw") && Checks.done(7) && !Step07EnoughMoney.enoughMoney(account, a)) { msg = "Not enough balance ❌"; ok = false; }
        else {
            boolean dep = action.equals("deposit");
            if (Checks.done(dep ? 5 : 6)) {
                if (dep) Step05Deposit.deposit(account, a); else Step06Withdraw.withdraw(account, a);
                String text = (dep ? "Deposited" : "Withdrew") + " ₹" + money(a);
                msg = text + " ✅"; ok = true;
                if (Checks.done(9)) Step09History.addHistory(history, text);
            }
        }
        return home302();
    }

    @PostMapping("/interest")
    public ResponseEntity<Void> interest() {
        if (account != null && Checks.done(10)) {
            Step10Interest.addInterest(account);
            msg = "4% interest added ✅"; ok = true;
            if (Checks.done(9)) Step09History.addHistory(history, "Interest added (4%)");
        }
        return home302();
    }

    @GetMapping("/close")
    public ResponseEntity<Void> close() {
        account = null; history.clear(); msg = ""; ok = true;
        return home302();
    }

    // ==============================================================
    //  API: ready-made. Call it with curl: commands/08_api_crud.txt
    //  (Java keeps data in memory. SQL for each call is in the comments.)
    // ==============================================================
    @GetMapping("/api/account")                          // SELECT * FROM accounts WHERE id = 1
    public ResponseEntity<Object> apiAccount() {
        if (account == null) return ResponseEntity.status(404).body(Map.of("error", "no account yet: open one on the page"));
        return ResponseEntity.ok(Map.of("name", account.name, "balance", account.balance, "history", history));
    }

    @PostMapping("/api/deposit")                         // UPDATE accounts SET balance = balance + ...
    public ResponseEntity<Object> apiDeposit(@RequestBody Map<String, Object> body) {
        return apiMove(body, 1);
    }

    @PostMapping("/api/withdraw")                        // UPDATE accounts SET balance = balance - ...
    public ResponseEntity<Object> apiWithdraw(@RequestBody Map<String, Object> body) {
        return apiMove(body, -1);
    }

    static ResponseEntity<Object> apiMove(Map<String, Object> body, int sign) {
        double amt;
        try { amt = Double.parseDouble(String.valueOf(body.get("amount"))); } catch (NumberFormatException e) { amt = 0; }
        if (account == null) return ResponseEntity.status(404).body(Map.of("error", "no account yet"));
        if (amt <= 0) return ResponseEntity.status(400).body(Map.of("error", "amount must be more than 0"));
        if (sign < 0 && amt > account.balance) return ResponseEntity.status(400).body(Map.of("error", "not enough balance"));
        account.balance = account.balance + sign * amt;
        history.add((sign > 0 ? "Deposited" : "Withdrew") + " ₹" + money(amt) + " (API)");
        return ResponseEntity.ok(Map.of("balance", account.balance));
    }

    static ResponseEntity<Void> home302() {
        return ResponseEntity.status(302).header("Location", "/").build();
    }
}
